#if os(macOS)
import AppKit
import TroveCore

/// Notices every copy on the Mac and hands it to the `ClipboardStore`. macOS has no notification
/// for pasteboard changes, so like other clipboard managers it checks the change count a few times a
/// second (a cheap integer read).
@MainActor
final class ClipboardWatcher {
    /// Markers apps set to say "don't keep this" (nspasteboard.org): password managers, generated text.
    static let skipTypes: Set<String> = [
        "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType", "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword", "de.petermaurer.TransientPasteboardType", "Pasteboard generator type",
    ]
    /// Apps whose copies are never recorded.
    static let ignoredApps: Set<String> = [
        "com.apple.keychainaccess", "com.apple.Passwords", "com.1password.1password", "com.agilebits.onepassword7",
        "com.bitwarden.desktop", "com.lastpass.LastPass", "com.dashlane.dashlanephonefinal", "org.keepassxc.keepassxc",
    ]

    private let store: ClipboardStore
    private var timer: Timer?
    private var lastChange = NSPasteboard.general.changeCount

    init(store: ClipboardStore) { self.store = store }

    func start() {
        guard timer == nil else { return }
        let timer = Timer(timeInterval: 0.4, repeats: true) { [weak self] _ in
            MainActor.assumeIsolated { self?.check() }
        }
        // Common modes, so copies still register while a menu is open or something is being dragged.
        RunLoop.main.add(timer, forMode: .common)
        self.timer = timer
    }

    func stop() {
        timer?.invalidate()
        timer = nil
    }

    private func check() {
        let pb = NSPasteboard.general
        guard pb.changeCount != lastChange else { return }
        lastChange = pb.changeCount
        guard store.enabled, pb.changeCount != ClipPasteboard.ownChangeCount else { return }
        let types = Set((pb.types ?? []).map(\.rawValue))
        guard types.isDisjoint(with: Self.skipTypes) else { return }
        let app = NSWorkspace.shared.frontmostApplication
        if let id = app?.bundleIdentifier, Self.ignoredApps.contains(id) { return }
        let name = app?.localizedName

        if let urls = pb.readObjects(forClasses: [NSURL.self], options: [.urlReadingFileURLsOnly: true]) as? [URL], !urls.isEmpty {
            Task { await store.capture(files: urls.map(\.path), sourceApp: name) }
            return
        }
        let text = pb.string(forType: .string)
        let imageData = pb.data(forType: .png) ?? pb.data(forType: .tiff).flatMap(Self.png(fromTIFF:))
        // The window and page it came from: read now, while that window is still in front.
        let (found, askBrowser) = ClipSourceProbe.immediate(app: app, pasteboard: pb)
        Task {
            var source = found
            if askBrowser, let bundle = found.bundle, let page = await ClipSourceProbe.pageURL(bundle: bundle) { source.url = page }
            // An image copied from a browser often comes with its address as text; keep the image.
            if let imageData, text == nil || ClipClassifier.classify(text ?? "") == .link {
                await store.capture(image: imageData, mime: "image/png", sourceApp: name, source: source)
            } else if let text {
                await store.capture(text: text, sourceApp: name, source: source)
            }
        }
    }

    private static func png(fromTIFF data: Data) -> Data? {
        NSBitmapImageRep(data: data)?.representation(using: .png, properties: [:])
    }
}
#endif

#if os(iOS)
import UIKit
import TroveCore

/// iOS doesn't let apps watch the clipboard in the background, so this saves whatever was copied
/// since last time whenever Trove comes to the front (and copies made inside Trove). The change
/// count is free to read; reading the contents shows iOS's "Allow Paste" question unless the user
/// chose Settings → Apps → Trove → Paste from Other Apps → Allow.
@MainActor
final class ClipboardWatcher {
    private let store: ClipboardStore
    private var observer: NSObjectProtocol?
    private var lastChange: Int {
        get { UserDefaults.standard.integer(forKey: "clipboard.lastChangeCount") }
        set { UserDefaults.standard.set(newValue, forKey: "clipboard.lastChangeCount") }
    }

    init(store: ClipboardStore) { self.store = store }

    func start() {
        guard observer == nil else { return }
        observer = NotificationCenter.default.addObserver(forName: UIPasteboard.changedNotification, object: nil, queue: .main) { [weak self] _ in
            MainActor.assumeIsolated { self?.check() }
        }
        check()
    }

    /// Saves the clipboard if it changed since the last look.
    func check() {
        let pb = UIPasteboard.general
        guard pb.changeCount != lastChange else { return }
        lastChange = pb.changeCount
        guard store.enabled, store.captureOnOpen, pb.changeCount != ClipPasteboard.ownChangeCount else { return }
        if pb.hasImages, !pb.hasURLs, let image = pb.image, let png = image.pngData() {
            Task { await store.capture(image: png, mime: "image/png", sourceApp: nil) }
        } else if let text = pb.string ?? pb.url?.absoluteString {
            Task { await store.capture(text: text, sourceApp: nil) }
        }
    }
}
#endif
